import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Features from './components/Features';
import ContactForm from './components/ContactForm';

const App = () => {
  const [jobs, setJobs] = useState([]);
  const [jobForm, setJobForm] = useState({
    title: '',
    company: '',
    location: '',
    description: '',
    link: ''
  });
  const [search, setSearch] = useState('');
  const [locationFilter, setLocationFilter] = useState('');
  const [companyFilter, setCompanyFilter] = useState('');

  // Fetch jobs from the API
  const fetchJobs = async () => {
    try {
      const response = await axios.get('http://localhost:5000/jobs', {
        params: { location: locationFilter, company: companyFilter }
      });
      setJobs(response.data);
    } catch (error) {
      console.error('Error fetching jobs', error);
    }
  };

  // Handle form input change
  const handleChange = (e) => {
    const { name, value } = e.target;
    setJobForm({ ...jobForm, [name]: value });
  };

  // Add a job
  const addJob = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:5000/jobs', jobForm);
      fetchJobs(); // Refresh the job listings
    } catch (error) {
      console.error('Error adding job', error);
    }
  };

  // Delete a job
  const deleteJob = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/jobs/${id}`);
      fetchJobs(); // Refresh the job listings
    } catch (error) {
      console.error('Error deleting job', error);
    }
  };

  // Handle search change
  const handleSearchChange = (e) => {
    setSearch(e.target.value);
    setLocationFilter('');
    setCompanyFilter('');
  };

  useEffect(() => {
    fetchJobs();
  }, [locationFilter, companyFilter]);

  return (
    <div>
      <Navbar />
      <Hero />
      <Features />

      <div className="job-listings">
        <h1>Job Listings</h1>

        {/* Search Bar */}
        <input
          type="text"
          placeholder="Search by job title"
          value={search}
          onChange={handleSearchChange}
        />

        <div className="filters">
          <input
            type="text"
            placeholder="Filter by location"
            value={locationFilter}
            onChange={(e) => setLocationFilter(e.target.value)}
          />
          <input
            type="text"
            placeholder="Filter by company"
            value={companyFilter}
            onChange={(e) => setCompanyFilter(e.target.value)}
          />
        </div>

        {/* Add Job Form */}
        <form onSubmit={addJob}>
          <input
            type="text"
            name="title"
            placeholder="Job Title"
            value={jobForm.title}
            onChange={handleChange}
          />
          <input
            type="text"
            name="company"
            placeholder="Company"
            value={jobForm.company}
            onChange={handleChange}
          />
          <input
            type="text"
            name="location"
            placeholder="Location"
            value={jobForm.location}
            onChange={handleChange}
          />
          <textarea
            name="description"
            placeholder="Job Description"
            value={jobForm.description}
            onChange={handleChange}
          />
          <input
            type="text"
            name="link"
            placeholder="Job Link"
            value={jobForm.link}
            onChange={handleChange}
          />
          <button type="submit">Add Job</button>
        </form>

        {/* Job Listings */}
        <div className="job-cards">
          {jobs
            .filter((job) => job.title.toLowerCase().includes(search.toLowerCase()))
            .map((job) => (
              <div key={job.id} className="job-card">
                <h3>{job.title}</h3>
                <p>{job.company} - {job.location}</p>
                <p>{job.description}</p>
                <a href={job.link} target="_blank" rel="noopener noreferrer">View Job</a>
                <button onClick={() => deleteJob(job.id)}>Delete</button>
              </div>
            ))}
        </div>
      </div>

      <ContactForm />
    </div>
  );
};

export default App;
